package android.widget;public class CompoundButton extends TextView {public OnCheckedChangeListener listener;boolean checked;public CompoundButton(android.content.Context c){super(c);}public interface OnCheckedChangeListener{void onCheckedChanged(CompoundButton b,boolean checked);}public void setOnCheckedChangeListener(OnCheckedChangeListener l){listener=l;}public void setChecked(boolean value){if(value==checked)return;checked=value;if(listener!=null)listener.onCheckedChanged(this,value);}public boolean isChecked(){return checked;}public boolean performClick(){if(!isEnabled())return false;setChecked(!checked);return true;}public void setButtonDrawable(android.graphics.drawable.Drawable d){} }
